function apiOrigin() {
  return (process.env.ALPHALAB_API_ORIGIN || 'http://127.0.0.1:8000').replace(/\/+$/, '')
}

async function run(input) {
  const base = apiOrigin() + '/api/data-sync/jobs'
  let url = base
  let options = { headers: { Accept: 'application/json', 'Content-Type': 'application/json' } }
  if (input.operation === 'list') {
    url += '?limit=' + Math.max(1, Math.min(200, Number(input.limit || 20)))
  } else if (input.operation === 'get') {
    const id = String(input.job_id || '').trim()
    if (!id) throw new Error('job_id is required for get')
    url += '/' + encodeURIComponent(id)
  } else if (input.operation === 'submit') {
    const body = { source: 'rq', template_id: String(input.template_id || 'rq.a_share_research'), force: input.force === true }
    if (input.datasets) body.datasets = input.datasets
    if (input.symbols) body.symbols = input.symbols.map(String)
    if (input.start) body.start = String(input.start)
    if (input.end) body.end = String(input.end)
    options = { ...options, method: 'POST', body: JSON.stringify(body) }
  } else if (input.operation === 'cancel') {
    if (input.confirm_cancel !== true) throw new Error('Cancelling a sync job requires an explicit user request and confirm_cancel=true')
    const id = String(input.job_id || '').trim()
    if (!id) throw new Error('job_id is required for cancel')
    url += '/' + encodeURIComponent(id) + '/cancel'
    options = { ...options, method: 'POST', body: '{}' }
  } else {
    throw new Error('Unsupported data sync job operation')
  }
  const response = await fetch(url, options)
  if (!response.ok) throw new Error('AlphaLab API ' + response.status + ': ' + await response.text())
  return response.json()
}
